/bin/bash -c "python3 - <<'PY'
from pathlib import Path
import re
for page in [17,19]:
    rows=[]
    for line in Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().splitlines():
        if not re.match(r'\\s*[a-z]',line):
            continue
        vals=re.findall(r'-?\\d+\\.\\d+',line)
        if page==17 and len(vals)>=4:
            rows.append((line.split()[0],*[float(v) for v in vals[:4]]))
        elif page==19 and len(vals)==3:
            rows.append((line.split()[0],*[float(v) for v in vals]))
    print('Page',page,'rows',len(rows))
    if page==17:
        for name, group in [('male-coded',rows[:20]),('female-coded',rows[20:]),('all',rows)]:
            print(name,'single mean SS',sum(r[1] for r in group)/len(group),'paired mean SS',sum(r[3] for r in group)/len(group))
    else:
        for name,group in [('minor',[r for r in rows if r[0].endswith('minor')]),('power',[r for r in rows if r[0].endswith('power')]),('all',rows)]:
            print(name,'single mean SS',sum(r[1] for r in group)/len(group),'paired mean SS',sum(r[2] for r in group)/len(group))
PY"
